using System.Collections;

class EnvVarCheck
{
    void CheckFlag()
    {
        // On Linux, set via: export MY_FLAG=""
        // .NET 9 breaking change: GetEnvironmentVariable returns null for
        // empty env vars on Linux, losing the distinction from "not set".
        // Use GetEnvironmentVariables() to check for existence instead.
        var val = Environment.GetEnvironmentVariable("MY_FLAG");
        IDictionary envVars = Environment.GetEnvironmentVariables();
        if (!envVars.Contains("MY_FLAG"))
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
    }
}

